add_action( 'woocommerce_after_shop_loop_item', 'perfectpixel_sales_count_for_admins', 20 );
add_action( 'woocommerce_single_product_summary', 'perfectpixel_sales_count_for_admins', 7 );

function perfectpixel_sales_count_for_admins() {
	global $product;
	if ( ! $product || ! current_user_can( 'manage_woocommerce' ) ) {
		return;
	}
	$stock = $product->managing_stock() ? wc_stock_amount( $product->get_stock_quantity() ) : ( $product->is_in_stock() ? '✓' : '✗' );
	printf(
		'<div class="perfectpixel-admin-sales" style="display:inline-block;margin:.25em 0;padding:.1em .5em;border:1px dashed #d63638;color:#d63638;font-size:.75em">Πωλήσεις: %s · Απόθεμα: %s</div>',
		esc_html( number_format_i18n( $product->get_total_sales() ) ),
		esc_html( $stock )
	);
}
